// Mock travel search + code scoring for ONE driver. No LLM here: every number below is computed, so the agent cannot invent prices.
// Real quotes from the dataset are used as-is. Gaps are filled with GENERATED options (source 'mock_generated'):
// same provider and route, fixed daily departures, deterministic price and sold-out flag (same input -> same answer).
// Ranking: on time first, then total cost, then driver convenience (hotel nights, terminal waiting).
const TERMINALS = { // dataset ferry_terminals (city level only); quote labels differ from terminal names.
  'West Baltic terminal': { id: 'terminal-west-baltic', city: 'Hamburg', country: 'DE' },
  'East Sweden terminal': { id: 'terminal-east-nordic', city: 'Stockholm', country: 'SE' },
  'South Finland terminal': { id: 'terminal-south-finland', city: 'Helsinki', country: 'FI' },
};
const ROUTES = [ // dataset FERRY quotes per route: median crossing hours, median available price, check-in 2 h before departure.
  { provider: 'Vela Coast Lines', from: 'West Baltic terminal', to: 'South Finland terminal', crossing_h: 28, price_cents: 42800, hours: ['12:00', '22:00'] },
  { provider: 'Vela Coast Lines', from: 'East Sweden terminal', to: 'South Finland terminal', crossing_h: 18, price_cents: 31750, hours: ['08:00', '19:00'] },
];
const ROAD = { // dataset terminal_road_estimates: city -> terminal, high minutes (excludes breaks and check-in).
  'Berlin|terminal-west-baltic': 270, 'Cologne|terminal-west-baltic': 390, 'Frankfurt|terminal-west-baltic': 420, 'Hamburg|terminal-west-baltic': 75,
  'Leipzig|terminal-west-baltic': 330, 'Munich|terminal-west-baltic': 630, 'Lyon|terminal-west-baltic': 1020, 'Copenhagen|terminal-south-baltic': 75,
  'Gothenburg|terminal-east-nordic': 420, 'Linköping|terminal-east-nordic': 210, 'Malmö|terminal-east-nordic': 510, 'Stockholm|terminal-east-nordic': 75, 'Uppsala|terminal-east-nordic': 105,
};
const HOTEL_CENTS = { Hamburg: 11580, Stockholm: 10740, Cologne: 6900, Gothenburg: 8900 }; // dataset hotel reservations (fare per night)
const HOTEL_DEFAULT_CENTS = () => c.settings.hotel_default_eur * 100; // no dataset hotel for other cities: estimate from the Settings page

const i = $('Start').first().json;
const c = $json;
if (!c.found) return [{ json: { ok: false, error: c.error } }];
const s = c.snapshot;
// Settings page: on-time spare before the window ends; approval time before any departure; slack kept before check-in.
const BUFFER_H = c.settings.on_time_spare_h, APPROVAL_MIN = c.settings.approval_buffer_min, SLACK_MIN = c.settings.booking_slack_min;
const H = 36e5, iso = (t) => new Date(t).toISOString().slice(0, 16) + 'Z', eur = (cents) => Math.round(cents) / 100;
const hash = (str) => { let h = 2166136261; for (const ch of str) h = Math.imul(h ^ ch.charCodeAt(0), 16777619); return (h >>> 0) / 4294967295; };
const win = (s.time_windows || []).find((w) => w.purpose === 'CUSTOMER_DELIVERY_PROMISE');
const pickup = (s.time_windows || []).find((w) => w.purpose === 'SELECTED_PICKUP_SLOT');
const now = Date.parse(s.snapshot_now);
const startCity = s.pickup?.city, deliveryCity = s.delivery?.city;
// Nothing can leave before a person approves: the earliest start is now + the approval buffer.
const readyAt = Math.max(now + APPROVAL_MIN * 6e4, i.ready_at ? Date.parse(i.ready_at) : pickup ? Date.parse(pickup.end_at) : now);
if (!win || Number.isNaN(readyAt)) return [{ json: { ok: false, error: 'No delivery promise window or bad ready_at; cannot plan.' } }];
const days = Math.min(Math.max(Number(i.days) || 4, 1), 7);
// Bookings that already failed on a real attempt count as sold out, so a re-plan does not pick them again.
const failed = new Set((c.plan_steps || []).filter((p) => p.kind === 'book_ferry' && p.status === 'failed' && /sold out/i.test(p.note)).map((p) => p.ref));

    // A sold-out alert or report since the case last closed: the order's current sailing (its ferry reservation, the driver's ferry
    // step or the last booked ferry) and any sailing the text names by option id or departure time count as sold out.
    // ponytail: text match on our own alerts and reports; a live provider availability check replaces it.
    const tl = c.case_timeline || [], closedAt = Math.max(0, ...tl.filter((t) => t.kind === 'closed').map((t) => t.id));
    const SOLD = /sold.?out|fully booked|no (vehicle )?(space|slot)|slot unavailable/i;
    const soldTexts = [...tl.filter((t) => t.id > closedAt && ['event', 'telegram_in', 'driver_reply', 'driver_message'].includes(t.kind) && SOLD.test(t.text)).map((t) => String(t.text)),
      ...(s.alerts || []).filter((a) => a.signal === 'FERRY_SOLD_OUT' && a.status !== 'RESOLVED').map((a) => String(a.summary || ''))];
    const current = soldTexts.length ? new Set([
      ...(s.travel_reservations || []).filter((r) => r.kind === 'FERRY' && r.departure_at).map((r) => r.departure_at.slice(0, 16)),
      ...(s.route_plan?.driver_steps || []).filter((x) => /FERRY/i.test(x.kind) && x.scheduled_start_at).map((x) => x.scheduled_start_at.slice(0, 16)),
    ]) : new Set();
    for (const p of (c.plan_steps || []).filter((p) => p.kind === 'book_ferry' && p.status === 'done')) { const id = (String(p.detail).match(/\b(gen-[\w-]+|travel-x[0-9a-f]+)/) || [])[1]; if (id && soldTexts.length) failed.add(id); } // the sailing we booked
    const alertSold = (id, departs) => soldTexts.length > 0 && (current.has(String(departs).slice(0, 16)) || soldTexts.some((x) => x.includes(id) || x.includes(String(departs).slice(0, 16)) || x.includes(String(departs).slice(0, 16).replace('T', ' '))));

const quotes = (s.travel_options || []).filter((q) => q.kind === 'FERRY');
const routes = ROUTES.filter((r) => TERMINALS[r.to].country === s.delivery?.country
  && (quotes.some((q) => q.from_city === r.from && q.to_city === r.to) || ROAD[`${startCity}|${TERMINALS[r.from].id}`]));
const options = [];
for (const r of routes) {
  const own = quotes.filter((q) => q.from_city === r.from && q.to_city === r.to);
  const known = own.find((q) => q.road_time_to_terminal_hours);
  const roadMin = ROAD[`${startCity}|${TERMINALS[r.from].id}`];
  // Road time: the dataset quote's own figure if any, else planning matrix + 45 min break per 4.5 h driving.
  const roadH = known ? known.road_time_to_terminal_hours : roadMin ? roadMin / 60 + Math.floor(roadMin / c.settings.break_after_min) * c.settings.break_min / 60 : null;
  const roadBasis = known ? 'dataset quote road_time_to_terminal_hours' : roadMin ? `planning matrix ${startCity} -> ${TERMINALS[r.from].city}, high estimate + breaks` : 'unknown';
  const hours = [...new Set(own.map((q) => q.departure_at.slice(11, 16)))];
  const sched = hours.length ? hours : r.hours;
  const ownPrice = own.filter((q) => q.quote_cents).map((q) => q.quote_cents);
  const base = ownPrice.length ? ownPrice.reduce((a, b) => a + b) / ownPrice.length : r.price_cents;
  for (const q of own) options.push({ option_id: q.id, source: 'dataset_quote', provider: q.provider, route: `${r.from} -> ${r.to}`,
    departs: q.departure_at, cutoff: q.check_in_cutoff_at, arrives: q.arrival_at, ticket_cents: q.quote_cents,
    status: failed.has(q.id) || alertSold(q.id, q.departure_at) ? 'SOLD_OUT' : q.status, note: failed.has(q.id) ? 'sold out at booking attempt' : alertSold(q.id, q.departure_at) ? 'sold out per alert or report' : q.capacity_note, roadH, roadBasis, r });
  const day0 = Date.UTC(new Date(readyAt).getUTCFullYear(), new Date(readyAt).getUTCMonth(), new Date(readyAt).getUTCDate());
  for (let d = 0; d <= days; d++) for (const hm of sched) {
    const dep = day0 + d * 24 * H + (Number(hm.slice(0, 2)) * 60 + Number(hm.slice(3))) * 6e4;
    if (dep < readyAt || own.some((q) => Date.parse(q.departure_at) === dep)) continue;
    const id = `gen-${TERMINALS[r.from].id.replace('terminal-', '')}-${iso(dep).replace(/[-:]/g, '')}`;
    const soldOut = hash(id + 'cap') < 0.25 || failed.has(id) || alertSold(id, iso(dep));
    options.push({ option_id: id, source: 'mock_generated', provider: r.provider, route: `${r.from} -> ${r.to}`,
      departs: iso(dep), cutoff: iso(dep - 2 * H), arrives: iso(dep + r.crossing_h * H),
      ticket_cents: soldOut ? null : Math.round(base * (0.8 + 0.4 * hash(id + 'price')) / 100) * 100,
      status: soldOut ? 'SOLD_OUT' : 'AVAILABLE_QUOTE', note: failed.has(id) ? 'sold out at booking attempt' : alertSold(id, iso(dep)) ? 'sold out per alert or report' : 'MOCK generated option, not a real quote', roadH, roadBasis, r });
  }
}

const nights = (from, to) => { let n = 0; for (let t = from; t < to; t += H) if (new Date(t).getUTCHours() === 2) n++; return n; }; // ponytail: one night per 02:00 UTC passed
const winStart = Date.parse(win.start_at), winEnd = Date.parse(win.end_at);
const scored = options.map((o) => {
  const out = { ...o }; delete out.r; delete out.roadH; delete out.roadBasis;
  const why = [];
  if (o.status !== 'AVAILABLE_QUOTE') why.push(`sold out (${o.note})`);
  if (o.roadH == null) why.push('no road time to this terminal');
  const atTerminal = readyAt + (o.roadH || 0) * H;
  if (o.roadH != null && atTerminal + SLACK_MIN * 6e4 > Date.parse(o.cutoff)) why.push(`cannot reach check-in with ${SLACK_MIN} min slack: at terminal ${iso(atTerminal)}, cutoff ${o.cutoff}`);
  if (why.length) return { ...out, usable: false, why_not: why.join('; ') };
  const destCity = TERMINALS[o.r.to].city;
  const transferH = destCity === deliveryCity ? c.settings.transfer_same_city_h : c.settings.transfer_other_city_h; // dataset quote notes: about 3 h from arrival terminal to delivery city
  const ready = Date.parse(o.arrives) + transferH * H;
  const deliverAt = Math.max(ready, winStart);
  const lateH = Math.max(0, (ready - winEnd) / H), onTime = ready + BUFFER_H * H <= winEnd;
  const originNights = nights(atTerminal, Date.parse(o.cutoff)), destNights = lateH ? 0 : nights(ready, deliverAt);
  const hotelCity = TERMINALS[o.r.from].city;
  const hotelOrigin = originNights * (HOTEL_CENTS[hotelCity] || HOTEL_DEFAULT_CENTS()), hotelDest = destNights * (HOTEL_CENTS[deliveryCity] || HOTEL_DEFAULT_CENTS());
  const waitH = (Date.parse(o.cutoff) - atTerminal) / H; // stuck near the departure terminal before check-in
  return { ...out, usable: true,
    at_terminal: iso(atTerminal), road_hours: +o.roadH.toFixed(1), road_basis: o.roadBasis,
    ready_to_deliver: iso(ready), delivery_window: `${win.start_at} -> ${win.end_at}`,
    on_time: onTime, late_hours: +lateH.toFixed(1), buffer_hours: +((winEnd - ready) / H).toFixed(1),
    hotel: [originNights && `${originNights} night(s) ${hotelCity}`, destNights && `${destNights} night(s) ${deliveryCity} waiting for delivery window`].filter(Boolean).join(' + ') || 'none',
    hotel_nights_origin: originNights, hotel_city_origin: hotelCity, hotel_nights_dest: destNights, hotel_city_dest: deliveryCity,
    hotel_price_basis: [hotelCity, deliveryCity].map((x) => `${x}: ${HOTEL_CENTS[x] ? 'dataset hotel fare' : 'MOCK flat estimate'}`).join(', '),
    ticket_eur: eur(o.ticket_cents), hotel_origin_eur: eur(hotelOrigin), hotel_dest_eur: eur(hotelDest), hotel_eur: eur(hotelOrigin + hotelDest), total_eur: eur(o.ticket_cents + hotelOrigin + hotelDest),
    hotel_nights: originNights + destNights, driver_wait_hours: +waitH.toFixed(1) };
});
const usable = scored.filter((o) => o.usable).sort((a, b) => b.on_time - a.on_time || a.late_hours - b.late_hours || a.total_eur - b.total_eur || a.hotel_nights - b.hotel_nights || a.driver_wait_hours - b.driver_wait_hours);
usable.forEach((o, k) => { o.rank = k + 1; });
const best = usable[0];
return [{ json: { ok: true, order_ref: c.order_ref,
  assumptions: { ready_at: iso(readyAt), ready_basis: `${i.ready_at ? 'given by caller' : 'end of selected pickup slot'}, never before now + ${APPROVAL_MIN} min approval time`, booking_slack_min: SLACK_MIN, start_city: startCity, delivery_city: deliveryCity,
    ranking: `on time (>= ${BUFFER_H} h spare) first,` + ' then total cost (ticket + hotel), then driver convenience (fewer hotel nights, less waiting at the terminal)',
    warning: 'mock_generated options and MOCK hotel estimates are simulated; dataset_quote prices are quotes, not bookings' },
  recommended: best ? best.option_id : null,
  summary: best ? `Best: ${best.provider} ${best.departs} (${best.source}), ${best.on_time ? 'on time' : best.late_hours + ' h late'}, total EUR ${best.total_eur} (ticket ${best.ticket_eur} + hotel ${best.hotel_eur}: ${best.hotel}).` : 'No usable option in the search range: a person must decide (later dates, other route, or change promise).',
  options: usable.slice(0, 6), not_usable: scored.filter((o) => !o.usable).map((o) => ({ option_id: o.option_id, source: o.source, departs: o.departs, why_not: o.why_not })) } }];
